{"content":"import type { Product } from "@/data/catalog";

/**
 * Lightweight generated product visual.
 * Real product photography from the ERP/PIM feed replaces this component's
 * inner markup later; keeping it isolated avoids heavy placeholder images.
 */
export function ProductThumb({ product, className = "" }: { product: Product; className?: string }) {
  const initials = product.manufacturer
    .replace(/[^A-Za-z& ]/g, "")
    .split(" ")
    .slice(0, 2)
    .map((w) => w[0])
    .join("");

  return (
    <div
      className={`flex flex-col items-center justify-center rounded-sm bg-sky-soft text-navy ${className}`}
      role="img"
      aria-label={`${product.manufacturer} ${product.name}`}
    >
      <span className="font-display text-2xl font-bold tracking-wide">{initials}</span>
      <span className="mt-1 px-2 text-center font-mono text-[0.65rem] uppercase text-navy-muted">
        {product.mfrPartNumber}
      </span>
    </div>
  );
}
